    check('FM103', 'Real trade is being considered close to a real, known expiry-day square-off deadline', 'high', 'require_confirmation', `Real expiry day, current time ${ctx.time}, configured square-off ${ctx.brokerSquareOffTime || 'not set'}.`, ctx.isExpiry === true && ctx.brokerSquareOffTime && typeof ctx.time === 'string' && ctx.time >= ctx.brokerSquareOffTime);
