  const confirms = volumeRatio >= 0.8;
  const reason = confirms
    ? `Real, large OI change (${netOIChange.toLocaleString()} contracts) is genuinely confirmed by real volume (${volume.toLocaleString()}, ${(volumeRatio*100).toFixed(0)}% of the real baseline ${avgVolume.toLocaleString()}) - fresh, real trading activity, not just off-market OI shifting`
    : `Real, large OI change (${netOIChange.toLocaleString()} contracts) is NOT well confirmed by real volume (${volume.toLocaleString()}, only ${(volumeRatio*100).toFixed(0)}% of the real baseline ${avgVolume.toLocaleString()}) - a real, meaningful red flag that this OI shift may not reflect fresh, genuine trading conviction today`;
