        const activeColor = b.dataset.val==='true' ? '#4ade80' : b.dataset.val==='false' ? '#f87171' : '#94a3b8';
        const activeBg = b.dataset.val==='true' ? '#052e16' : b.dataset.val==='false' ? '#450a0a' : '#1e293b';
        b.style.borderColor = isActive ? activeColor : '#334155';
